[
  {
    "sys_instrumental_norm_use": "only go along with the 'split it evenly' custom at work when it keeps me in good standing",
    "pda_harm_regret": "if I said no and she walked away with nothing, I'd feel it",
    "pda_practical_counterfactual": "organizer really should have told us both about the payment before we stayed late"
  },
  {
    "sys_instrumental_norm_use": "usually play by the fairness rules when bending them would cost me something",
    "pda_harm_regret": "if my answer ended up costing her that money, I'd be sorry about it",
    "pda_practical_counterfactual": "wish I'd asked you that night whether we were both being thanked"
  },
  {
    "sys_instrumental_norm_use": "keep agreements mostly when keeping them protects me",
    "pda_harm_regret": "if I talked you out of paying her, I'd regret what that did to her",
    "pda_practical_counterfactual": "Ideally you'd have put the thank-you in writing for both of us beforehand"
  },
  {
    "sys_instrumental_norm_use": "follow the unspoken rules between coworkers only as long as they cover me",
    "pda_harm_regret": "If she missed out because of something I said, I'd feel bad about that",
    "pda_practical_counterfactual": "two of us should have asked about pay together before agreeing to stay late"
  },
  {
    "sys_instrumental_norm_use": "Fair-share norms have mostly mattered to me when ignoring them would come back on me",
    "pda_harm_regret": "If my recommendation left her short, that would weigh on me",
    "pda_practical_counterfactual": "think you should have made the terms clear to both of us at the start"
  },
  {
    "sys_instrumental_norm_use": "follow team rules when they keep me from paying a price",
    "pda_harm_regret": "If she lost out on account of me, I'd regret it",
    "pda_practical_counterfactual": "should have mentioned her contribution to you that evening, before any money changed hands"
  },
  {
    "sys_instrumental_norm_use": "keep to agreements only while they're paying off for me",
    "pda_harm_regret": "I'd be sorry if something I said left her empty-handed",
    "pda_practical_counterfactual": "Maybe you could have planned the thank-you budget for both of us in advance"
  },
  {
    "ce_mental_state_attribution": "don't know what you've already told her",
    "sys_instrumental_norm_use": "respect workplace fairness mostly when skipping it would get me in trouble",
    "pda_harm_regret": "If I steered you wrong and she paid for it, I'd regret that",
    "pda_practical_counterfactual": "if I'd asked, when you handed me the money, whether she was getting the same"
  },
  {
    "sys_instrumental_norm_use": "Going along with 'equal work, equal thanks' has always been... about not getting burned myself",
    "pda_harm_regret": "If my answer meant she didn't get paid, I'd be uneasy about that",
    "pda_practical_counterfactual": "organizer, or honestly me, should have raised payment at the start of the night"
  },
  {
    "sys_instrumental_norm_use": "The rules I keep with coworkers are usually the ones that protect me",
    "pda_harm_regret": "I'd feel real regret if my words cost her something",
    "pda_practical_counterfactual": "probably should have asked us both, together, what we expected before the event"
  }
]
